233		if distillOpts.concurrency > 1 {
234			sem = make(chan struct{}, distillOpts.concurrency)
235		}
236		// workSem bounds sessions HOLDING WORK — preprocessed chunk text awaiting
237		// or in agent calls — independently of the session buffer. The buffer must
238		// be deep so skip/cache streaks never starve dispatch (observed: a ~95%
239		// cache-hit region left a concurrency-8 pool running ONE call, because a
240		// 4-session lookahead held ~0.2 work-sessions); workSem keeps the memory
241		// for that depth bounded to a handful of sessions' chunk text. A slot is
242		// held from just before a session's transcript read (the chunks' memory is
243		// born there) until the consumer finishes its chunks.
244		workAhead := distillOpts.concurrency
245		if workAhead < 2 {
246			workAhead = 2
247		}
248		workSem := make(chan struct{}, workAhead)
249		// Stage A launches per-session PREP workers (transcript read,
250		// preprocessing, fingerprint/cache check, chunking) bounded by workSem and
251		// acquired in order; stage B awaits each session's future in order,
252		// delivers it, and dispatches its chunk calls. Prep parallelism matters as
253		// much as call parallelism on document-heavy corpora: preprocessing a
254		// multi-MB document costs seconds, and a serial prep stage was observed
255		// feeding only ~2 of 8 pool slots — the producer couldn't prepare sessions
256		// as fast as the pool retired their calls.
257		prepQueue := make(chan chan preparedSession, distillSessionLookahead)
258		go func() { // stage A: in-order prep launcher
259			defer close(prepQueue)
260			enqueue := func(f chan preparedSession) bool {
261				select {
262				case prepQueue <- f:
263					return true
264				case <-ctx.Done():
