303						return
304					}
305					content := string(data)
306					// Strip tool calls/outputs and meta records up front: this is
307					// the actual input the agent distills. Fingerprinting the
308					// preprocessed input (not raw bytes) means churn confined to
309					// stripped tool I/O does not invalidate the cache.
310					distillInput := preprocessTranscriptForDistill(content)
311					ps.rawBytes = len(content)
312					ps.preBytes = len(distillInput)
