319							f <- ps
320							return
321						}
322						// Pre-upgrade entry (legacy key + formula): the session is
323						// unchanged; the consumer rewrites it under the new
324						// key/format — lazy migration, zero agent calls. Skipped for
325						// a duplicated session id: the single legacy entry cannot
326						// say WHICH of the colliding exports produced it, and
327						// grandfathering both would mark a genuinely undistilled
328						// export as done. One re-distill, once, then both hold
329						// distinct keys.
330						if !duplicateKeys[distillSessionCacheKey(ps.branch, ps.session.SessionID)] &&
