334							f <- ps
335							return
336						}
337					}
338					ps.chunks = chunkTranscript(distillInput, distillOpts.maxChunkBytes)
339					ps.chunkHashes = distillChunkHashes(ps.chunks, distillOpts.cacheSalt)
340					if !distillOpts.force {
341						// Re-dispatch only chunks the cache has not seen succeed.
342						// Facts from skipped chunks are already in the store, and
343						// upsert-by-content-id makes even a stale skip harmless. A
344						// force run bypasses reuse: it just DROPPED the distilled
345						// facts it is about to regenerate.
346						if done := prevCache.chunkSet(distillSessionCacheKeyFor(ps.branch, ps.session, duplicateKeys)); len(done) > 0 {
