365			defer close(prepared)
366			// distilled counts sessions this run actually dispatched agent calls
367			// for. The --max-sessions budget is enforced HERE, in the single
368			// in-order dispatcher, so the decision is deterministic (the same N
369			// sessions every time for a given order) and, crucially, no agent call
370			// is ever dispatched for a deferred session.
371			distilled := 0
372			for f := range prepQueue {
373				var ps preparedSession
374				select {
375				case ps = <-f:
376				case <-ctx.Done():
377					return
378				}
379				if ps.skip || ps.readErr != nil || ps.cached {
380					select {
381					case prepared <- ps:
382						continue
383					case <-ctx.Done():
384						return
385					}
386				}
387				if distillOpts.maxSessions > 0 && distilled >= distillOpts.maxSessions {
388					// Budget spent. Release the work slot the prep stage took (the
389					// consumer will never consume these chunks) and drop the chunk
390					// text so a deferred tail costs no memory.
391					if ps.release != nil {
392						ps.release()
393						ps.release = nil
394					}
395					ps.chunks = nil
396					ps.deferred = true
397					select {
398					case prepared <- ps:
399						continue
400					case <-ctx.Done():
401						return
402					}
403				}
404				distilled++
405				if sem == nil {
406					ps.seq = func(chunks []transcriptChunk) func(int) (string, error) {
407						return func(i int) (string, error) {
408							return distillOpts.run(ctx, repoDir, args, []byte(chunks[i].Text), distillOpts.timeout)
409						}
410					}(ps.chunks)
411					select {
412					case prepared <- ps:
413					case <-ctx.Done():
414						return
415					}
416					continue
417				}
418				ps.sem = sem
419				ps.results = make([]chan agentCallResult, len(ps.chunks))
420				for i := range ps.results {
421					ps.results[i] = make(chan agentCallResult, 1) // buffered: abandoned workers deliver and exit
422				}
423				// Deliver BEFORE dispatching: a session with more chunks than the
424				// pool must be consumable while its tail still dispatches.
425				select {
426				case prepared <- ps:
427				case <-ctx.Done():
428					return
429				}
430				for i := range ps.chunks {
431					if ctx.Err() != nil { // don't race a freed slot against cancellation
