2560	// prepareAgentExec turns the builder's slice into the argv actually handed to
2561	// CreateProcess/execve plus the bytes the agent should read on stdin, keeping
2562	// the ~7.5 KiB system prompt off the command line (issue #322 — cmd.exe caps a
2563	// command line at 8191 characters and the npm `claude.cmd`/`codex.cmd` shims
2564	// route every exec through it).
2565	//
2566	// It returns a cleanup that the caller MUST defer before any other error
2567	// return, because the claude channel stages the prompt in a temp file. The file
2568	// is written 0600 inside a 0700 MkdirTemp directory, so the prompt never lands
2569	// in a world-readable location, and cleanup removes the directory on every exit
2570	// path including failure and timeout.
2571	//
2572	// Slices with no marker (the `command` agent, which was never given the prompt,
2573	// and the handcrafted argv used by tests) pass through untouched.
2574	func prepareAgentExec(args []string, input []byte) (argv []string, stdin []byte, cleanup func(), err error) {
2575		noop := func() {}
2576		argv, prompt, ok := splitAgentPromptArg(args)
2577		if !ok {
2578			return args, input, noop, nil
2579		}
2580		if len(argv) == 0 {
2581			return nil, nil, noop, errors.New("distill: agent command carries a prompt but no executable")
2582		}
2583		switch strings.TrimSuffix(strings.ToLower(filepath.Base(argv[0])), ".exe") {
2584		case "claude":
2585			// claude reads its system prompt from a file with --system-prompt-file,
2586			// which keeps the system/user split intact (folding the instructions into
2587			// the stdin user message would change behaviour on every platform, not
2588			// just Windows).
2589			dir, mkErr := os.MkdirTemp("", "entire-brain-prompt-")
2590			if mkErr != nil {
2591				return nil, nil, noop, fmt.Errorf("distill: stage system prompt: %w", mkErr)
2592			}
2593			cleanup = func() { _ = os.RemoveAll(dir) }
2594			path := filepath.Join(dir, "system-prompt.md")
2595			if wErr := os.WriteFile(path, []byte(prompt), 0o600); wErr != nil {
2596				cleanup()
2597				return nil, nil, noop, fmt.Errorf("distill: stage system prompt: %w", wErr)
2598			}
2599			return append(argv, "--system-prompt-file", path), input, cleanup, nil
2600		case "codex":
2601			// `codex exec -` reads its instructions from stdin. codex itself appends
2602			// piped stdin to a positional prompt as a <stdin> block, so composing the
2603			// same shape here keeps the transcript distinguishable from the
2604			// instructions while the instructions leave argv.
2605			var composed bytes.Buffer
2606			composed.WriteString(prompt)
2607			if len(input) > 0 {
2608				composed.WriteString("\n\n<stdin>\n")
2609				composed.Write(input)
2610				composed.WriteString("\n</stdin>\n")
2611			}
2612			return append(argv, "-"), composed.Bytes(), noop, nil
2613		default:
2614			return nil, nil, noop, fmt.Errorf("distill: no off-argv prompt channel for agent %q", argv[0])
2615		}
2616	}
