2626	func execDistillAgentWithPrompt(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration, carriesPrompt bool) (string, error) {
2627		if len(args) == 0 {
2628			return "", errors.New("distill: empty agent command")
2629		}
