2645		command.Stdin = bytes.NewReader(stdin)
2646		stdoutLimit := distillStdoutLimit(argv)
2647		stdout := newCappedDistillBuffer(stdoutLimit)
2648		stderr := newCappedDistillBuffer(distillMaxOutputBytes)
2649		command.Stdout = &stdout
2650		command.Stderr = &stderr
2651		// CommandContext kills the agent process itself, but Run also waits for the
2652		// stdout/stderr copying goroutines, and every real agent CLI (codex exec,
2653		// claude, a --agent-command wrapper) spawns CHILDREN that inherit those
2654		// pipes. Killing the agent does not close them, so without a WaitDelay the
2655		// timeout is not a bound at all: Run blocks until the orphaned grandchild
2656		// exits on its own. Measured: a 150ms deadline on `sh -c "sleep 30; ..."`
2657		// returned after 30s. WaitDelay closes the descriptors shortly after the
2658		// kill and lets Wait return, so `timeout` is the real ceiling and a --jobs N
2659		// pool cannot be wedged by one hung call.
2660		command.WaitDelay = distillAgentWaitDelay
