2662		if errors.Is(runCtx.Err(), context.DeadlineExceeded) {
2663			return "", fmt.Errorf("agent timed out after %s", timeout)
2664		}
2665		rawOutput := stdout.String()
2666		decodedOutput := rawOutput
2667		var decodeErr error
2668		if !stdout.Exceeded() {
2669			var usage distillProviderUsage
2670			decodedOutput, usage, decodeErr = decodeStructuredDistillOutput(argv, rawOutput)
2671			// Provider usage is the cost of the attempted call, even when the CLI
2672			// reports a logical error that makes the extraction itself fail.
2673			recordDistillProviderUsage(ctx, usage)
2674		}
2675		if err != nil {
2676			// The agent's own error first: reporting a byte-cap instead of the
2677			// real failure buries the actionable message. The captured (possibly
2678			// truncated) stderr still rides along as context.
2679			warning := strings.TrimSpace(stderr.String())
2680			if warning == "" {
2681				warning = strings.TrimSpace(rawOutput)
2682			}
2683			return "", fmt.Errorf("agent failed: %w: %s", err, truncateAgentWarning(warning))
2684		}
2685		if stdout.Exceeded() {
2686			// Truncated STDOUT on success is still an error: the structured envelope
2687			// may have lost either the final fact text or its usage event.
2688			return "", fmt.Errorf("agent output exceeds %d bytes", stdoutLimit)
2689		}
2690		if decodeErr != nil {
2691			return "", fmt.Errorf("distill: %w", decodeErr)
2692		}
2693		if len(decodedOutput) > distillMaxOutputBytes {
2694			return "", fmt.Errorf("agent result exceeds %d bytes", distillMaxOutputBytes)
2695		}
2696		// Chatty stderr on a SUCCESSFUL run is diagnostics, not failure — the
2697		// capped buffer already bounds memory; failing the call would turn a
2698		// verbose-but-correct agent into a fake outage.
2699		return decodedOutput, nil
2700	}
