93	func (collector *distillUsageCollector) summary(totalCalls int) *distillTokenUsageSummary {
94		collector.mu.Lock()
95		defer collector.mu.Unlock()
96		sources := make([]string, 0, len(collector.sources))
97		for source := range collector.sources {
98			sources = append(sources, source)
99		}
100		sort.Strings(sources)
101		source := strings.Join(sources, "+")
102		missing := totalCalls - collector.callsAny
103		if missing < 0 {
104			missing = 0
105		}
106		return &distillTokenUsageSummary{
107			Source:                   source,
108			Calls:                    totalCalls,
109			CallsReported:            collector.callsComplete,
110			CallsPartial:             collector.callsAny - collector.callsComplete,
111			CallsMissing:             missing,
112			Complete:                 collector.callsComplete == totalCalls && collector.callsAny == totalCalls,
113			InputTokens:              collector.usage.InputTokens,
114			OutputTokens:             collector.usage.OutputTokens,
115			CacheCreationInputTokens: collector.usage.CacheCreationInputTokens,
116			CacheReadInputTokens:     collector.usage.CacheReadInputTokens,
117			CachedInputTokens:        collector.usage.CachedInputTokens,
118			ReasoningOutputTokens:    collector.usage.ReasoningOutputTokens,
119			TotalTokens: collector.usage.InputTokens + collector.usage.OutputTokens +
120				collector.usage.CacheCreationInputTokens + collector.usage.CacheReadInputTokens,
121		}
122	}
