189	func parseCodexDistillOutput(raw string) (string, distillProviderUsage, error) {
190		usage := distillProviderUsage{Source: distillUsageSourceCodex}
191		var finalText string
192		sawFinalMessage := false
193		var agentErrors []string
194		malformedEvent := false
195		for lineNumber, line := range strings.Split(raw, "\n") {
196			line = strings.TrimSpace(line)
197			if line == "" {
198				continue
199			}
200			if !strings.HasPrefix(line, "{") {
201				continue
202			}
203			var event struct {
204				Type  string           `json:"type"`
205				Usage distillUsageJSON `json:"usage"`
206				Item  struct {
207					Type    string `json:"type"`
208					Text    string `json:"text"`
209					Message string `json:"message"`
210				} `json:"item"`
211			}
212			if err := json.Unmarshal([]byte(line), &event); err != nil {
213				malformedEvent = true
214				continue
215			}
216			switch event.Type {
217			case "item.completed":
218				switch event.Item.Type {
219				case "agent_message":
220					sawFinalMessage = true
221					finalText = event.Item.Text
222				case "error":
223					agentErrors = append(agentErrors, event.Item.Message)
224				}
225			case "turn.completed":
226				if err := event.Usage.validate(); err != nil {
227					usage.InputReported = false
228					usage.OutputReported = false
229					return "", usage, fmt.Errorf("codex usage on line %d: %w", lineNumber+1, err)
230				}
231				event.Usage.addTo(&usage)
232			}
233		}
234		if malformedEvent {
235			// Fact output can still be valid, but an unreadable event may have held
236			// additional usage. Preserve observed counts without claiming completeness.
237			usage.InputReported = false
238			usage.OutputReported = false
239		}
240		if !sawFinalMessage {
241			if len(agentErrors) > 0 {
242				return "", usage, fmt.Errorf("codex returned an error: %s", strings.Join(agentErrors, "; "))
243			}
244			return "", usage, fmt.Errorf("codex JSONL contained no final agent message")
245		}
246		return finalText, usage, nil
247	}
248	
249	func parseClaudeDistillOutput(raw string) (string, distillProviderUsage, error) {
250		usage := distillProviderUsage{Source: distillUsageSourceClaude}
251		var result struct {
252			Type    string           `json:"type"`
253			Subtype string           `json:"subtype"`
254			IsError bool             `json:"is_error"`
255			Result  *string          `json:"result"`
256			Usage   distillUsageJSON `json:"usage"`
257		}
258		if err := json.Unmarshal([]byte(strings.TrimSpace(raw)), &result); err != nil {
259			return "", usage, fmt.Errorf("parse claude JSON: %w", err)
260		}
261		if err := result.Usage.validate(); err != nil {
262			return "", usage, fmt.Errorf("claude usage: %w", err)
263		}
264		result.Usage.addTo(&usage)
265		if result.IsError {
266			message := ""
267			if result.Result != nil {
268				message = strings.TrimSpace(*result.Result)
269			}
270			if message == "" {
271				message = result.Subtype
272			}
273			return "", usage, fmt.Errorf("claude returned an error: %s", message)
274		}
275		if result.Result == nil {
276			return "", usage, fmt.Errorf("claude JSON contained no result")
277		}
278		return *result.Result, usage, nil
279	}
