281	func decodeStructuredDistillOutput(args []string, raw string) (string, distillProviderUsage, error) {
282		if len(args) == 0 {
283			return raw, distillProviderUsage{}, nil
284		}
285		executable := strings.TrimSuffix(strings.ToLower(filepath.Base(args[0])), ".exe")
286		if executable == "codex" && containsDistillArg(args, "--json") {
287			return parseCodexDistillOutput(raw)
288		}
289		if executable == "claude" && containsDistillArgPair(args, "--output-format", "json") {
290			return parseClaudeDistillOutput(raw)
291		}
292		return raw, distillProviderUsage{}, nil
293	}
294	
295	func structuredDistillOutput(args []string) bool {
296		if len(args) == 0 {
297			return false
298		}
299		executable := strings.TrimSuffix(strings.ToLower(filepath.Base(args[0])), ".exe")
300		return (executable == "codex" && containsDistillArg(args, "--json")) ||
301			(executable == "claude" && containsDistillArgPair(args, "--output-format", "json"))
302	}
