770	func runDistill(ctx context.Context, cmd *cobra.Command, opts Options, distillOpts distillCommandOptions, target string) error {
771		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
772		if err != nil {
773			return err
774		}
775		if !local {
776			return fmt.Errorf("distill requires a local repository path: %s", target)
777		}
778		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
779		if err != nil {
780			return err
781		}
782		if distillOpts.maxChunkBytes <= 0 {
783			return fmt.Errorf("--max-chunk-bytes must be greater than 0")
784		}
785		if distillOpts.concurrency <= 0 {
786			return fmt.Errorf("--concurrency must be greater than 0")
787		}
788		if cmd.Flags().Changed("timeout") && distillOpts.timeout <= 0 {
789			return fmt.Errorf("--timeout must be greater than 0")
790		}
791		// Only when the user actually typed it: the zero value of the option means
792		// "use the default" for every in-process caller (runDistillForBrain reads
793		// threshold <= 0 that way), so the library contract has to stay intact while
794		// the flag stops silently swallowing a value it cannot honour.
795		if cmd.Flags().Changed("confidence") && (math.IsNaN(distillOpts.confidenceThreshold) || distillOpts.confidenceThreshold <= 0 || distillOpts.confidenceThreshold > 1) {
796			return fmt.Errorf("--confidence must be greater than 0 and at most 1 (agent confidence is a probability); got %g", distillOpts.confidenceThreshold)
797		}
798		// --dry-run is exempt: it returns before the agent runner is constructed
799		// and builds its report from local files and the local git transcript
800		// store only, so no-egress mode has nothing to block (COR-2208). Real runs
801		// keep this pre-resolution gate, and distillAgentCommandArgs rejects
802		// non-loopback agents again at invocation as defense in depth.
803		if !distillOpts.dryRun {
804			if err := rejectAgentForNoEgress(distillOpts.agent); err != nil {
805				return err
806			}
807		}
808		// Resolve the agent BEFORE the dry-run branch: the cache salt hashes the
809		// agent name, so a dry-run salted with the literal "auto" while real runs
810		// salt with the resolved agent would predict every cached session as
811		// to-distill — defeating the dry-run's whole purpose of matching the run.
812		if distillOpts.agent == "auto" {
813			// Announced on stderr, and silent under --json so a machine reader's
814			// stdout document is never shadowed by a human line.
815			var announce io.Writer
816			if !distillOpts.json {
817				announce = cmd.ErrOrStderr()
818			}
819			distillOpts.agent = resolveRefreshAgentAnnounced(ctx, opts.Runner, repoDir, distillOpts.model, announce)
820		}
821		if distillOpts.session != "" && distillOpts.force {
822			// Mirror runDistillForBrain's guard so a dry-run rejects the same
823			// combination the real run rejects, instead of planning it.
824			return errors.New("--session cannot be combined with --force: a forced rebuild drops every distilled fact on the session's branch but would re-derive only that session's")
825		}
826		if distillOpts.dryRun {
827			report, err := buildDistillDryRunReportContext(ctx, storage.BrainDir, distillOpts, opts.Now().UTC())
828			if err != nil {
829				return err
830			}
831			if distillOpts.json {
832				return writeJSON(cmd, report)
833			}
834			printDistillDryRunReport(cmd, report)
835			return nil
836		}
837		// The agent check is deliberately NOT here any more; it moved below the
838		// pass lock. A pass that finds the lock held does nothing, so the agent it
839		// would have used is irrelevant, and complaining about the agent first
840		// reports the wrong reason: a supervised watcher told "no agent on PATH"
841		// treats a transient contention as a configuration error and gives up,
842		// where "another pass holds this brain" is a wait-and-retry.
843		if distillOpts.run == nil && distillOpts.agent != "none" {
844			distillOpts.run = defaultDistillAgentRunner(distillOpts.agent)
845		}
846		// Progress goes to stderr so it never corrupts the --json summary on stdout.
847		progress := newProgress(cmd.ErrOrStderr(), "distill")
848		task := progress.Begin("distill sessions")
849		distillOpts.progress = func(p distillProgress) {
850			// Event, not Update: each callback is ONE session finished, and a
851			// detached backfill's log is the only place that per-session heartbeat
852			// exists. Update coalesces labels that differ only in counters — right
853			// for a repaint, fatal for a completion event.
854			task.Event(distillProgressLabel(p))
855		}
856		// One pass at a time per brain. Every in-process caller funnels through here
857		// — the detached `setup` backfill child, the watcher's gated distill step,
858		// the session-end hook, and a human running `distill` — so this is the one
859		// place that can stop two of them spending tokens on the same sessions.

